  const q = [root]
  let head = 0, i = 1
  while (head < q.length && i < tokens.length) {
    const node = q[head++]
    if (i < tokens.length) {
      if (tokens[i] !== 'null') {
        node.left = new TreeNode(Number(tokens[i]))
        q.push(node.left)
      }
      i++
    }
