def gen(rng):
    def serialize(val, left, right):
        toks = []
        q = [0]
        h = 0
        while h < len(q):
            u = q[h]
            h += 1
            if u is None:
                toks.append('null')
            else:
                toks.append(str(val[u]))
                q.append(left[u] if left[u] != -1 else None)
                q.append(right[u] if right[u] != -1 else None)
        while toks and toks[-1] == 'null':
            toks.pop()
        return ' '.join(toks)

    def random_tree(n, V, mode):
        val = [rng.randint(-V, V) for _ in range(n)]
        left = [-1] * n
        right = [-1] * n
        if mode == 'random':
            slots = [(0, 0), (0, 1)]
            for i in range(1, n):
                k = rng.randrange(len(slots))
                slots[k], slots[-1] = slots[-1], slots[k]
                p, side = slots.pop()
                if side == 0:
                    left[p] = i
                else:
                    right[p] = i
                slots.append((i, 0))
                slots.append((i, 1))
        elif mode == 'complete':
            for i in range(n):
                if 2 * i + 1 < n:
                    left[i] = 2 * i + 1
                if 2 * i + 2 < n:
                    right[i] = 2 * i + 2
        elif mode == 'left':
            for i in range(n - 1):
                left[i] = i + 1
        elif mode == 'right':
            for i in range(n - 1):
                right[i] = i + 1
        elif mode == 'zigzag':
            for i in range(n - 1):
                if i % 2 == 0:
                    left[i] = i + 1
                else:
                    right[i] = i + 1
        return serialize(val, left, right)

    tests = ["5", "-3", "1 2", "1 null 2", "1 2 3", "1 2 3 4 5 null 6", "7 null 8 9", "0 0 0 0 0 0 0"]
    for n in (2, 3, 4, 5, 6, 8, 10, 14):
        for _ in range(3):
            tests.append(random_tree(n, 20, 'random'))
    tests.append(random_tree(7, 9, 'complete'))
    tests.append(random_tree(40, 100, 'random'))
    tests.append(random_tree(2000, 10**4, 'random'))
    tests.append(random_tree(50000, 10**4, 'random'))
    tests.append(random_tree(50000, 10**4, 'complete'))
    tests.append(random_tree(5000, 10**4, 'left'))
    tests.append(random_tree(5000, 10**4, 'right'))
    tests.append(random_tree(5000, 10**4, 'zigzag'))
    return tests
